import { useState } from "react";
import { Mail, Phone, MapPin, Send, User, Clock, CheckCircle } from "lucide-react";

export default function Contact() {
  const [formData, setFormData] = useState({
    name: "",
    email: "",
    phone: "",
    subject: "",
    message: "",
  });

  const [isSubmitting, setIsSubmitting] = useState(false);
  const [submitStatus, setSubmitStatus] = useState(null);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData((prev) => ({
      ...prev,
      [name]: value
    }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setIsSubmitting(true);
    setSubmitStatus(null);

    // Validation simple
    if (!formData.name || !formData.email || !formData.subject || !formData.message) {
      setSubmitStatus({ type: "error", message: "Veuillez remplir tous les champs obligatoires." });
      setIsSubmitting(false);
      return;
    }

    try {
      const response = await fetch("http://localhost:5000/api/contact", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(formData),
      });

      const data = await response.json();

      if (data.success) {
        setSubmitStatus({ type: "success", message: "Message envoyé avec succès ! Nous vous répondrons rapidement." });
        setFormData({ name: "", email: "", phone: "", subject: "", message: "" });
      } else {
        setSubmitStatus({ type: "error", message: data.message || "Une erreur est survenue, veuillez réessayer." });
      }
    } catch (error) {
      setSubmitStatus({ type: "error", message: "Erreur de connexion au serveur. Veuillez réessayer." });
    } finally {
      setIsSubmitting(false);
      setTimeout(() => setSubmitStatus(null), 5000);
    }
  };

  const contactInfo = [
    { icon: Mail, title: "Email", content: "enzo@gmail.com", subContent: "RAELLoic@gmail.com", color: "from-blue-500 to-cyan-500", gradient: "bg-gradient-to-br", action: "mailto:enzo@gmail.com" },
    { icon: Phone, title: "Téléphone", content: "+261 38 809 913 56", subContent: "+261 38 809 913 56", color: "from-emerald-500 to-green-500", gradient: "bg-gradient-to-br", action: "tel:+2613880991356" },
    { icon: MapPin, title: "Bureaux", content: "123 Avenue des Champs-Élysées", subContent: "75008 Paris, France", color: "from-purple-500 to-pink-500", gradient: "bg-gradient-to-br", action: "https://maps.google.com/?q=123+Champs-Élysées,Paris" },
    { icon: Clock, title: "Horaires", content: "Lun - Ven: 9h - 18h", subContent: "Samedi: 10h - 14h", color: "from-amber-500 to-orange-500", gradient: "bg-gradient-to-br", action: null }
  ];

  const subjects = ["Demande générale", "Support technique", "Devis / Proposition", "Partenariat", "Autre"];

  return (
    <div className="min-h-screen bg-gradient-to-br from-gray-50 via-white to-indigo-50 py-16 px-4 sm:px-6 lg:px-8">
      <div className="max-w-7xl mx-auto">
        {/* En-tête */}
        <div className="text-center mb-16">
          <h1 className="text-4xl md:text-5xl lg:text-6xl font-bold text-gray-900 mb-4">
            Contactez-<span className="bg-gradient-to-r from-indigo-600 to-blue-600 bg-clip-text text-transparent">nous</span>
          </h1>
          <p className="text-gray-600 text-lg md:text-xl max-w-3xl mx-auto leading-relaxed">
            Notre équipe est à votre écoute pour répondre à toutes vos questions et accompagner vos projets
          </p>
        </div>

        <div className="grid lg:grid-cols-3 gap-8 lg:gap-12">
          {/* Infos contact */}
          <div className="lg:col-span-1">
            <div className="sticky top-8">
              <div className="bg-gradient-to-br from-white to-gray-50 rounded-3xl shadow-xl p-8 border border-gray-100">
                <h2 className="text-2xl font-bold text-gray-900 mb-8 flex items-center gap-3">
                  <div className="w-10 h-10 bg-gradient-to-br from-indigo-500 to-blue-500 rounded-lg flex items-center justify-center">
                    <User className="w-5 h-5 text-white" />
                  </div>
                  Nos coordonnées
                </h2>
                <div className="space-y-6">
                  {contactInfo.map((item, idx) => (
                    <a
                      key={idx}
                      href={item.action || "#"}
                      target={item.action?.startsWith("http") ? "_blank" : "_self"}
                      rel="noopener noreferrer"
                      className={`block group ${item.action ? "cursor-pointer hover:scale-[1.02]" : "cursor-default"}`}
                    >
                      <div className="flex items-start gap-4 p-4 rounded-2xl transition-all duration-300 group-hover:bg-gray-50">
                        <div className={`flex-shrink-0 w-12 h-12 ${item.gradient} ${item.color} rounded-xl flex items-center justify-center shadow-md`}>
                          <item.icon className="w-6 h-6 text-white" />
                        </div>
                        <div className="flex-1">
                          <h3 className="font-semibold text-gray-900">{item.title}</h3>
                          <p className="text-gray-700 mt-1">{item.content}</p>
                          {item.subContent && <p className="text-gray-500 text-sm mt-1">{item.subContent}</p>}
                        </div>
                      </div>
                    </a>
                  ))}
                </div>
              </div>
            </div>
          </div>

          {/* Formulaire */}
          <div className="lg:col-span-2">
            <div className="bg-white rounded-3xl shadow-xl p-8 md:p-10 border border-gray-100">
              <div className="mb-10">
                <h2 className="text-3xl font-bold text-gray-900 mb-3">Envoyez-nous un message</h2>
                <p className="text-gray-600">Remplissez le formulaire ci-dessous et nous vous répondrons dans les plus brefs délais</p>
              </div>

              {/* Statut */}
              {submitStatus && (
                <div className={`mb-8 p-4 rounded-2xl ${submitStatus.type === "success" ? "bg-green-50 border border-green-200" : "bg-red-50 border border-red-200"}`}>
                  <div className="flex items-center gap-3">
                    {submitStatus.type === "success" ? (
                      <CheckCircle className="w-5 h-5 text-green-600" />
                    ) : (
                      <div className="w-5 h-5 rounded-full bg-red-600 flex items-center justify-center">
                        <span className="text-white text-xs">!</span>
                      </div>
                    )}
                    <p className={submitStatus.type === "success" ? "text-green-700" : "text-red-700"}>{submitStatus.message}</p>
                  </div>
                </div>
              )}

              <form onSubmit={handleSubmit} className="space-y-8">
                <div className="grid md:grid-cols-2 gap-8">
                  <div>
                    <label className="block text-gray-700 font-medium mb-2">Nom complet *</label>
                    <input type="text" name="name" value={formData.name} onChange={handleChange} placeholder="Votre nom et prénom" className="w-full px-5 py-3 bg-gray-50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none transition-all duration-300" required />
                  </div>
                  <div>
                    <label className="block text-gray-700 font-medium mb-2">Email *</label>
                    <input type="email" name="email" value={formData.email} onChange={handleChange} placeholder="email@exemple.com" className="w-full px-5 py-3 bg-gray-50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none transition-all duration-300" required />
                  </div>
                  <div>
                    <label className="block text-gray-700 font-medium mb-2">Téléphone</label>
                    <input type="tel" name="phone" value={formData.phone} onChange={handleChange} placeholder="+261 38 89 913 56" className="w-full px-5 py-3 bg-gray-50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none transition-all duration-300" />
                  </div>
                  <div>
                    <label className="block text-gray-700 font-medium mb-2">Sujet *</label>
                    <select name="subject" value={formData.subject} onChange={handleChange} className="w-full px-5 py-3 bg-gray-50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none transition-all duration-300" required>
                      <option value="">Sélectionnez un sujet</option>
                      {subjects.map((subj, idx) => (<option key={idx} value={subj}>{subj}</option>))}
                    </select>
                  </div>
                </div>

                <div>
                  <label className="block text-gray-700 font-medium mb-2">Message *</label>
                  <textarea name="message" value={formData.message} onChange={handleChange} rows="6" placeholder="Décrivez votre projet ou votre question..." className="w-full px-5 py-3 bg-gray-50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none transition-all duration-300 resize-none" required />
                </div>

                <div className="pt-4">
                  <button type="submit" disabled={isSubmitting} className={`w-full md:w-auto min-w-[200px] px-8 py-4 bg-gradient-to-r from-indigo-600 to-blue-600 text-white font-semibold rounded-xl shadow-lg hover:shadow-xl transition-all duration-300 flex items-center justify-center gap-3 ${isSubmitting ? "opacity-75 cursor-not-allowed" : ""}`}>
                    {isSubmitting ? (
                      <>
                        <div className="w-5 h-5 border-2 border-white border-t-transparent rounded-full animate-spin"></div>
                        Envoi en cours...
                      </>
                    ) : (
                      <>
                        Envoyer le message <Send className="w-5 h-5" />
                      </>
                    )}
                  </button>
                  <p className="text-gray-500 text-sm mt-4">* Champs obligatoires. Vos données sont traitées confidentiellement.</p>
                </div>
              </form>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}
